#include <array>
#include <cstdint>
#include <iostream>
#include <string>
#include <vector>

enum class Level { info, warn, error };

struct Line
{
    Level level{};
    std::string text{};
};

class Log
{
public:
    void add(Level l, std::string text) {}
    std::vector<std::size_t> visible(Level minimum) const { return {}; }

private:
    std::vector<Line> m_lines{};
    std::array<int, 3> m_counts{};
};

int main()
{
    Log log{};
    log.add(Level::warn, "low memory");
}
